action.command:
cd /workspace && cat > /tmp/dump-env.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
cd /workspace
cat > /tmp/dump-env.mjs <<'EOF'
import { buildProfileEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';
import { writeFileSync } from 'node:fs';
const env = buildProfileEnv('local-builder', { rootDir: '/workspace' });
let out = '';
for (const [k,v] of Object.entries(env)) {
  if (typeof v !== 'string') continue;
  out += `${k}=${v}\n`;
}
writeFileSync('/tmp/local-builder.env', out);
console.log('wrote /tmp/local-builder.env with', Object.keys(env).length, 'vars');
EOF
pnpm exec tsx /tmp/dump-env.mjs
SH
bash /tmp/dump-env.sh && echo "=== sample vars ===" && grep -E '^(SVA_RUNTIME_PROFILE|VITE_SVA_RUNTIME_PROFILE|SVA_MOCK_AUTH|VITE_MOCK_AUTH|VITE_PUBLIC_BUILDER_KEY|IAM_DATABASE_URL|REDIS_URL|SVA_PUBLIC_BASE_URL|SVA_ENABLE_MONITORING|ENABLE_OTEL|SVA_MAINSERVER_REQUIRED)=' /tmp/local-builder.env

